import React from "react";

const Results = ({ data }) => (
  <div className="card">
    <h2>Meeting Summary</h2>
    <p>{data.summary}</p>

    <h3>MOM</h3>
    <p>{data.mom}</p>

    <h3>Tasks</h3>
    <ul>
      {data.tasks?.map((t, i) => (
        <li key={i}>{t.task} - {t.deadline}</li>
      ))}
    </ul>
  </div>
);

export default Results;
